        for fn in filenames:
            if not fn.endswith(".md"):
                continue
            path = os.path.join(dirpath, fn)
            try:
                with open(path, "r", encoding="utf-8", errors="replace") as f:
                    text = f.read()
            except Exception:
                continue
            if text.startswith("---"):
                end = text.find("\n---", 3)
                fm = text[:end] if end != -1 else text[:2000]
            else:
                continue
            m = status_re.search(fm)
            if m:
                v = m.group(1).strip().strip("'\"")
                status_counts[v] += 1
print("status: value counts:")
for k,v in status_counts.most_common(30):
    print(f"  {v:4d}  {k!r}")
