import sys, re, yaml
sys.path.insert(0, "10_System/scripts")
import validate_note_frontmatter as v
from pathlib import Path

root = Path(".")
files = []
for folder in v.SCOPED_FOLDERS:
    p = root / folder
    if p.exists():
        files.extend(p.rglob("*.md"))

bad_yaml = []
for f in files:
    try:
        content = f.read_text(encoding="utf-8")
    except Exception as e:
        bad_yaml.append((str(f), f"read error: {e}"))
        continue
    m = re.match(r"^---\n(.*?)\n---", content, re.DOTALL)
    if not m:
        continue
    try:
        yaml.safe_load(m.group(1))
    except Exception as e:
        bad_yaml.append((str(f), str(e)))

print(f"Scanned {len(files)} files, {len(bad_yaml)} with YAML parse errors")
for f, e in bad_yaml:
    print(" -", f, "->", e)
EOF
